#!/usr/bin/env python3
"""Finite verification of the chain generated by the 19-symbol C/N survivor."""

from __future__ import annotations

from collections import Counter
from typing import TypeAlias

Term: TypeAlias = str | tuple[str, "Term"] | tuple[str, "Term", "Term"]


def parse(text: str, pos: int = 0) -> tuple[Term, int]:
    symbol = text[pos]
    if symbol == "C":
        left, pos = parse(text, pos + 1)
        right, pos = parse(text, pos)
        return ("C", left, right), pos
    if symbol == "N":
        arg, pos = parse(text, pos + 1)
        return ("N", arg), pos
    return symbol, pos + 1


def polish(term: Term) -> str:
    if isinstance(term, str):
        return term
    if term[0] == "N":
        return "N" + polish(term[1])
    return "C" + polish(term[1]) + polish(term[2])


def weight(term: Term) -> int:
    if isinstance(term, str):
        return 1
    if term[0] == "N":
        return 1 + weight(term[1])
    return 1 + weight(term[1]) + weight(term[2])


def connective_count(term: Term) -> int:
    if isinstance(term, str):
        return 0
    if term[0] == "N":
        return 1 + connective_count(term[1])
    return 1 + connective_count(term[1]) + connective_count(term[2])


def variable_counts(term: Term) -> Counter[str]:
    if isinstance(term, str):
        return Counter({term: 1})
    if term[0] == "N":
        return variable_counts(term[1])
    return variable_counts(term[1]) + variable_counts(term[2])


def apply(subst: dict[str, Term], term: Term) -> Term:
    if isinstance(term, str):
        return apply(subst, subst[term]) if term in subst else term
    if term[0] == "N":
        return ("N", apply(subst, term[1]))
    return ("C", apply(subst, term[1]), apply(subst, term[2]))


def occurs(var: str, term: Term, subst: dict[str, Term]) -> bool:
    term = apply(subst, term)
    if isinstance(term, str):
        return term == var
    if term[0] == "N":
        return occurs(var, term[1], subst)
    return occurs(var, term[1], subst) or occurs(var, term[2], subst)


class UnificationFailure(Exception):
    pass


def unify(left: Term, right: Term, subst: dict[str, Term] | None = None) -> dict[str, Term]:
    subst = {} if subst is None else subst
    left, right = apply(subst, left), apply(subst, right)
    if left == right:
        return subst
    if isinstance(left, str):
        if occurs(left, right, subst):
            raise UnificationFailure("occurs check")
        subst[left] = right
        return subst
    if isinstance(right, str):
        if occurs(right, left, subst):
            raise UnificationFailure("occurs check")
        subst[right] = left
        return subst
    if left[0] != right[0]:
        raise UnificationFailure("symbol clash")
    if left[0] == "N":
        return unify(left[1], right[1], subst)
    return unify(left[2], right[2], unify(left[1], right[1], subst))


fresh_counter = 0


def freshen(term: Term, names: dict[str, str] | None = None) -> Term:
    global fresh_counter
    names = {} if names is None else names
    if isinstance(term, str):
        if term not in names:
            fresh_counter += 1
            names[term] = f"v{fresh_counter}"
        return names[term]
    if term[0] == "N":
        return ("N", freshen(term[1], names))
    return ("C", freshen(term[1], names), freshen(term[2], names))


def canonicalize(term: Term) -> Term:
    names: dict[str, str] = {}

    def walk(node: Term) -> Term:
        if isinstance(node, str):
            names.setdefault(node, f"x{len(names)}")
            return names[node]
        if node[0] == "N":
            return ("N", walk(node[1]))
        return ("C", walk(node[1]), walk(node[2]))

    return walk(term)


def cd(major: Term, minor: Term) -> Term:
    major, minor = freshen(major), freshen(minor)
    if isinstance(major, str) or major[0] != "C":
        raise UnificationFailure("major is not an implication")
    subst = unify(minor, major[1])
    return canonicalize(apply(subst, major[2]))


def left_heavy(term: Term) -> bool:
    assert not isinstance(term, str) and term[0] == "C"
    left, right = term[1], term[2]
    lc, rc = variable_counts(left), variable_counts(right)
    return connective_count(left) > connective_count(right) and all(
        lc[var] >= count for var, count in rc.items()
    )


candidate, end = parse("CCpCCqrCNsNrCCrpCrs")
assert end == 19

chain = [candidate]
for _ in range(25):
    chain.append(cd(candidate, chain[-1]))

assert all(left_heavy(term) for term in chain)
for i, major in enumerate(chain[:25]):
    for j, minor in enumerate(chain[:25]):
        if i == 0:
            assert cd(major, minor) == chain[j + 1]
        else:
            try:
                cd(major, minor)
            except UnificationFailure:
                pass
            else:
                raise AssertionError(f"unexpected CD result from T{i}, T{j}")

print("Verified T0-major chain and left-heavy invariant through T25.")
print("Verified every CD(T_i,T_j), 1 <= i <= 24 and 0 <= j <= 24, fails.")
print("Weights:", ", ".join(str(weight(term)) for term in chain[:10]))
